{"command": "cat > ~/search.py <<'EOF'
import workcell, math, sys

def call(*a):
    return workcell.call("robot", *a)

cx, cy = map(float, sys.argv[1:3])
hintx, hinty = float(sys.argv[3]), float(sys.argv[4]) if len(sys.argv)>4 else (cx, cy)

# candidate offsets within r<=1.45 of (cx,cy), step 0.6, ordered by distance to hint
pts = []
step = 0.6
n = 2  # -1.2,-0.6,0,0.6,1.2
for i in range(-n, n+1):
    for j in range(-n, n+1):
        dx, dy = i*step, j*step
        if math.hypot(dx, dy) <= 1.45 and (dx, dy) != (0,0):
            pts.append((dx, dy))
pts.sort(key=lambda p: math.hypot(cx+p[0]-hintx, cy+p[1]-hinty))

for dx, dy in pts:
    x, y = cx+dx, cy+dy
    r = call("insert", x, y)
    print(f"try ({x:.2f},{y:.2f}): ok={r.ok} {r.text.strip()}", flush=True)
    if r.ok:
        print(f"SEATED at ({x:.2f},{y:.2f}) offset=({dx:+.2f},{dy:+.2f})")
        break
EOF
