import workcell, sys, math
def rc(*a): return workcell.call("robot", *a)
cx, cy = float(sys.argv[1]), float(sys.argv[2])
step = float(sys.argv[3]) if len(sys.argv)>3 else 0.3
pts = [(0,0)]
for i in range(-1,2):
    for j in range(-1,2):
        if (i,j)!=(0,0): pts.append((i*step, j*step))
pts.sort(key=lambda p: math.hypot(*p))
for dx,dy in pts:
    x,y = cx+dx, cy+dy
    r = rc("insert", x, y)
    print(f"({x:.2f},{y:.2f}): ok={r.ok} {r.text.strip()[:80]}", flush=True)
    if r.ok:
        print(f"SEATED offset=({dx:+.2f},{dy:+.2f})"); sys.exit(0)
print("NOT SEATED in grid")
EOF
