{"command": "cat > ~/dopin.py <<'EOF'
import workcell, sys, math, re
def rc(*a): return workcell.call("robot", *a)
pin, x, y = sys.argv[1], float(sys.argv[2]), float(sys.argv[3])
r = rc("pick", pin); print(r.text.strip(), flush=True)
if not r.ok: sys.exit(1)
r = rc("insert", x, y)
print(f"direct ({x:.2f},{y:.2f}): ok={r.ok}", flush=True)
if r.ok: sys.exit(0)
for ang in (0, 90, 180, 270):
    x2, y2 = x + 0.15*math.cos(math.radians(ang)), y + 0.15*math.sin(math.radians(ang))
    r = rc("insert", round(x2,2), round(y2,2))
    print(f"ring ({x2:.2f},{y2:.2f}): ok={r.ok}", flush=True)
    if r.ok: sys.exit(0)
print("FAILED", pin); sys.exit(1)
EOF
